package com.contextgraph.repository; import com.contextgraph.model.Document; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface DocumentRepository extends JpaRepository<Document,Long>{List<Document> findByOwnerIdOrderByCreatedAtDesc(Long ownerId); Optional<Document> findByIdAndOwnerId(Long id,Long ownerId); boolean existsByChecksumAndOwnerId(String checksum,Long ownerId);}